    font-size: 22px;
    font-weight: 900;
    color: var(--txt);
    letter-spacing: -.4px;
    line-height: 1.1;
  }
  .hdr-sub {
    margin-top: 3px;
    font-size: 10.5px;
    font-weight: 600;
    color: var(--muted);
    letter-spacing: 2.5px;
    text-transform: uppercase;
    font-family: 'Inter', sans-serif;
  }
  .hdr-badge {
    position: relative;
    background: linear-gradient(135deg, var(--accent), var(--accent-d));
    color: #03160E;
