    font-size: 10.5px;
    font-weight: 800;
    padding: 3px 10px;
    border-radius: 999px;
    font-family: 'Inter', sans-serif;
  }

  /* Rest day */
  .day-card.rest .day-hdr {
    background: linear-gradient(90deg, rgba(255,122,89,.08), transparent);
  }
  .day-card.rest .day-tag { background: rgba(255,122,89,.12); color: #FF9C7A; }
  .rest-body {
    padding: 16px 18px;
    color: #FFC9B8;
    font-size: 13.5px;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .rest-icon {
    font-size: 20px;
  }

